import java.util.*;

public class Main {
    static int n;
    static int[] a;
    static int[] b;
    static boolean[] used;
    static long wins;

    static void dfs(int depth, int score) {
        if (depth == n) {
            if (score > 0) {
                wins++;
            }
            return;
        }
        for (int i = 0; i < n; i++) {
            if (used[i]) {
                continue;
            }
            used[i] = true;
            int gain = a[depth] + b[i];
            if (b[i] > a[depth]) {
                dfs(depth + 1, score + gain);
            } else {
                dfs(depth + 1, score - gain);
            }
            used[i] = false;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        a = new int[n];
        b = new int[n];
        used = new boolean[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            b[i] = sc.nextInt();
        }
        dfs(0, 0);
        System.out.println(wins);
    }
}
