import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][];
        int r = 0;
        int c = 0;
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    r = i;
                    c = j;
                }
            }
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        String dirs = "UDLR";
        int d = 0;
        for (char command : sc.next().toCharArray()) {
            d = dirs.indexOf(command);
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] != '#') {
                r = nr;
                c = nc;
            }
        }
        System.out.println(r + " " + c + " " + dirs.charAt(d));
    }
}
