import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] dx = {0, 0, -1, 1};
        int[] dy = {1, -1, 0, 0};
        Map<String, int[]> groups = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            int d = sc.nextInt();
            int e = sc.nextInt();
            String key = (x + dx[d]) + ":" + (y + dy[d]);
            int[] group = groups.computeIfAbsent(key, k -> new int[2]);
            group[0]++;
            group[1] += e;
        }

        int answer = 0;
        for (int[] group : groups.values()) {
            if (group[0] >= 2) {
                answer += group[1];
            }
        }
        System.out.println(answer);
    }
}
